using ModelContextProtocol.Server;
using System.Text.Json;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithTools<DevOpsTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

// --- Tools ---

[McpServerToolType]
public static class DevOpsTools
{
    [McpServerTool(Name = "get_status"), Description("Gets the current service health status.")]
    public static object GetStatus()
    {
        return new
        {
            status = "healthy",
            uptime = TimeSpan.FromHours(42).ToString(),
            timestamp = DateTimeOffset.UtcNow
        };
    }

    [McpServerTool(Name = "echo"), Description("Echoes back the provided message.")]
    public static string Echo(string message) => $"Echo: {message}";
}

// --- Resources ---

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app_settings",
        Title = "Application Settings", MimeType = "application/json")]
    public static string GetAppSettings()
    {
        var settings = new Dictionary<string, object>
        {
            ["environment"] = "production",
            ["logLevel"] = "Information",
            ["maxConnections"] = 100,
            ["featureFlags"] = new Dictionary<string, bool>
            {
                ["darkMode"] = true,
                ["betaFeatures"] = false
            }
        };
        return JsonSerializer.Serialize(settings, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/version", Name = "app_version",
        Title = "Application Version", MimeType = "application/json")]
    public static string GetVersion()
    {
        return JsonSerializer.Serialize(new
        {
            version = "2.1.0",
            buildDate = "2026-06-15",
            commitSha = "abc1234"
        });
    }
}

[AttributeUsage(AttributeTargets.Method)]
public class DescriptionAttribute : System.ComponentModel.DescriptionAttribute
{
    public DescriptionAttribute(string description) : base(description) { }
}
